"""Exact-to-the-penny order pricing. Works in whole pennies, then converts."""

from dataclasses import dataclass
from decimal import Decimal
from typing import List

_RATES = {"standard": 20, "reduced": 5, "zero": 0}  # percent


@dataclass(frozen=True)
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass(frozen=True)
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal


def _pence(value: Decimal) -> int:
    sign, digits, exp = value.as_tuple()
    n = int("".join(map(str, digits)) or "0")
    shift = exp + 2
    if shift >= 0:
        n *= 10 ** shift
    else:
        n = (n + 10 ** (-shift) // 2) // 10 ** (-shift)
    return -n if sign else n


def _money(pence: int) -> Decimal:
    sign = "-" if pence < 0 else ""
    pence = abs(pence)
    return Decimal("%s%d.%02d" % (sign, pence // 100, pence % 100))


def _pct(pence: int, percent: int) -> int:
    """percent of pence, rounded half up (pence >= 0)."""
    return (pence * percent + 50) // 100


def price_order(order, catalog) -> Quote:
    items = []
    for sku, quantity in order.lines:
        product = catalog[sku]
        unit = _pence(product.price)
        gross = quantity * unit
        percent = 10 if quantity >= 50 else 5 if quantity >= 10 else 0
        discount = _pct(gross, percent)
        items.append((product, sku, quantity, unit, gross, discount, gross - discount))

    nets = [item[6] for item in items]
    subtotal = sum(nets)
    order_discount = _pct(subtotal, 3) if subtotal >= 50000 else 0

    shares = [0] * len(items)
    if order_discount and subtotal:
        shares = [order_discount * n // subtotal for n in nets]
        remainders = [order_discount * n % subtotal for n in nets]
        left = order_discount - sum(shares)
        ranked = sorted(range(len(items)), key=lambda i: (-remainders[i], i))
        for i in ranked[:left]:
            shares[i] += 1

    tax = 0
    for item, share in zip(items, shares):
        tax += _pct(item[6] - share, _RATES[item[0].tax])

    lines = [
        QuoteLine(sku, quantity, _money(unit), _money(gross), _money(-discount if discount else 0), _money(net))
        for (_p, sku, quantity, unit, gross, discount, net) in items
    ]
    return Quote(
        lines,
        _money(subtotal),
        _money(-order_discount if order_discount else 0),
        _money(tax),
        _money(subtotal - order_discount + tax),
    )
"""Shipped-so-far, fulfilment, invoices and the report."""

from decimal import Decimal
from typing import Dict, List, Optional, Tuple

from .parsing import Order
from .pricing import Quote, price_order
from .shelves import sorted_movements


def shipped_so_far(order, sku: str, movements) -> int:
    """Units of sku already sent for this order (capped at the quantity ordered)."""
    ordered = dict(order.lines).get(sku, 0)
    note = "order " + order.id
    sent = -sum(
        m.quantity
        for m in movements
        if m.sku == sku and m.quantity < 0 and m.note == note
    )
    return min(ordered, max(sent, 0))


def shipped_lines(order, movements) -> List[Tuple[str, int]]:
    return [(sku, shipped_so_far(order, sku, movements)) for sku, _ in order.lines]


def status_of(order, movements) -> str:
    shipped = shipped_lines(order, movements)
    if all(done >= qty for (_, qty), (_, done) in zip(order.lines, shipped)):
        return "complete"
    if not any(done for _, done in shipped):
        return "open"
    return "partial"


def available(sku: str, on_date, movements) -> int:
    """How many units of sku can leave on on_date without breaking any later movement."""
    balance = 0
    at_date = 0
    lowest_later = None
    for m in sorted_movements(movements):
        if m.sku != sku:
            continue
        balance += m.quantity
        if m.date > on_date:
            lowest_later = balance if lowest_later is None else min(lowest_later, balance)
        else:
            at_date = balance
    best = at_date if lowest_later is None else min(at_date, lowest_later)
    return max(best, 0)


def plan_fulfil(order, on_date, movements):
    """Per order line: (sku, shipped now, backordered). Plus the resulting status."""
    results = []
    for sku, quantity in order.lines:
        before = shipped_so_far(order, sku, movements)
        owed = quantity - before
        now = min(owed, available(sku, on_date, movements))
        results.append((sku, now, owed - now))
    if all(back == 0 for _, _, back in results):
        state = "complete"
    elif all(
        shipped_so_far(order, sku, movements) + now == 0
        for sku, now, _ in results
    ):
        state = "open"
    else:
        state = "partial"
    return results, state


def invoice_order(order, movements) -> Optional[Order]:
    lines = [(sku, n) for sku, n in shipped_lines(order, movements) if n > 0]
    if not lines:
        return None
    return Order(order.id, order.date, order.customer, lines)


def _sort_key(order):
    digits = order.id[3:].lstrip("0")
    return (order.date, len(digits), digits, order.id)


def report_rows(orders, catalog, movements) -> List[Dict[str, object]]:
    zero = Decimal("0.00")
    rows = []
    for order in sorted(orders, key=_sort_key):
        shipped = sum(n for _, n in shipped_lines(order, movements))
        invoice = invoice_order(order, movements)
        rows.append(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "status": status_of(order, movements),
                "ordered": sum(q for _, q in order.lines),
                "shipped": shipped,
                "quoted": price_order(order, catalog).total,
                "invoiced": price_order(invoice, catalog).total if invoice else zero,
            }
        )
    return rows
"""The `stockroom` command: argument parsing, file reading, output, exit codes."""

import csv
import io
import json
import os
import re
import sys
from decimal import Decimal

from . import orders as orders_mod
from . import shelves
from .parsing import (
    Movement,
    ParseError,
    ORDER_ID_RE,
    SKU_RE,
    parse_catalog,
    parse_date,
    parse_movements,
    parse_orders,
)
from .pricing import price_order

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"

USAGE = """\
usage: stockroom [--dir DIR] COMMAND ...
  stock [--json]                       what is on the shelves
  low [--json]                         what to buy
  history SKU [--json]                 movements of one product
  receive DATE SKU QUANTITY [NOTE]     add stock in
  ship DATE SKU QUANTITY [NOTE]        add stock out
  quote ORDER [--json]                 price an order
  fulfil ORDER DATE                    ship what the shelves allow
  invoice ORDER [--json]               price what has shipped
  report [--format text|csv|json]      one row per order
"""

# command -> (needs movements, needs orders)
_FILES = {
    "stock": (True, False),
    "low": (True, False),
    "history": (True, False),
    "receive": (True, False),
    "ship": (True, False),
    "quote": (False, True),
    "fulfil": (True, True),
    "invoice": (True, True),
    "report": (True, True),
}
_JSON_COMMANDS = ("stock", "low", "history", "quote", "invoice")
_PLAIN_COMMANDS = ("receive", "ship", "fulfil")
_POSITIONALS = {
    "stock": (0, 0),
    "low": (0, 0),
    "history": (1, 1),
    "receive": (3, 4),
    "ship": (3, 4),
    "quote": (1, 1),
    "fulfil": (2, 2),
    "invoice": (1, 1),
    "report": (0, 0),
}


class UsageError(Exception):
    """Something wrong with the command line (exit 2)."""


class FileProblem(Exception):
    """A file or folder cannot be read (exit 2)."""


class Refusal(Exception):
    """A data mistake or a refused request (exit 1)."""


def _amount(value: Decimal) -> str:
    if value == 0:
        value = abs(value)
    return "%.2f" % value


def _dump(obj) -> str:
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def _lines(rows) -> str:
    return "".join(row + "\n" for row in rows)


# ---------------------------------------------------------------- arguments

def _split_args(argv):
    """Pull out --dir (anywhere); return (directory, remaining args)."""
    directory = None
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise UsageError("--dir needs a folder")
            directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            directory = arg[len("--dir="):]
        else:
            rest.append(arg)
        i += 1
    return directory, rest


def _is_option(arg: str) -> bool:
    return arg.startswith("--") or (arg.startswith("-") and len(arg) > 1)


def _parse_args(argv):
    directory, rest = _split_args(argv)
    if not rest:
        raise UsageError("no command given")
    command, args = rest[0], rest[1:]
    if command not in _FILES:
        raise UsageError("unknown command %r" % command)

    options = {"json": False, "format": "text"}
    if command in _PLAIN_COMMANDS:
        positionals = list(args)
    else:
        positionals = []
        i = 0
        while i < len(args):
            arg = args[i]
            if arg == "--json" and command in _JSON_COMMANDS:
                options["json"] = True
            elif command == "report" and arg == "--format":
                if i + 1 >= len(args):
                    raise UsageError("--format needs a value")
                options["format"] = args[i + 1]
                i += 1
            elif command == "report" and arg.startswith("--format="):
                options["format"] = arg[len("--format="):]
            elif _is_option(arg):
                raise UsageError("unknown option %r" % arg)
            else:
                positionals.append(arg)
            i += 1
        if command == "report" and options["format"] not in ("text", "csv", "json"):
            raise UsageError("bad --format %r (text, csv or json)" % options["format"])

    low, high = _POSITIONALS[command]
    if not low <= len(positionals) <= high:
        raise UsageError("wrong number of arguments for %s" % command)

    date = None
    if command in ("receive", "ship"):
        date = parse_date(positionals[0])
        if date is None:
            raise UsageError("bad date %r (want YYYY-MM-DD)" % positionals[0])
        if len(positionals) == 4:
            try:
                positionals[3].encode("utf-8")
            except UnicodeEncodeError:
                raise UsageError("note is not valid UTF-8") from None
    elif command == "fulfil":
        date = parse_date(positionals[1])
        if date is None:
            raise UsageError("bad date %r (want YYYY-MM-DD)" % positionals[1])
    return command, directory, positionals, options, date


# -------------------------------------------------------------------- files

def _read(directory, name, required):
    path = os.path.join(directory, name)
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        if required:
            raise FileProblem("%s: file not found" % name) from None
        return b""
    except OSError as err:
        raise FileProblem("%s: %s" % (name, err.strerror or err)) from None
    try:
        raw.decode("utf-8")
    except UnicodeDecodeError:
        raise FileProblem("%s: not valid UTF-8" % name) from None
    return raw


def _parse(name, func, *args):
    try:
        return func(*args)
    except ParseError as err:
        raise Refusal("%s: %s" % (name, err)) from None


def _append(directory, existing: bytes, text: str):
    prefix = b"\n" if existing and not existing.endswith(b"\n") else b""
    try:
        with open(os.path.join(directory, MOVEMENTS), "ab") as handle:
            handle.write(prefix + text.encode("utf-8"))
    except OSError as err:
        raise FileProblem("%s: %s" % (MOVEMENTS, err.strerror or err)) from None


# ----------------------------------------------------------------- commands

def _stock(catalog, movements, options):
    levels = shelves.stock_levels(catalog, movements)
    rows = [
        (sku, levels[sku], shelves.status(levels[sku], catalog[sku].reorder), catalog[sku].name)
        for sku in sorted(catalog)
    ]
    if options["json"]:
        return _dump(
            [{"sku": s, "name": n, "onhand": o, "status": st} for s, o, st, n in rows]
        )
    return _lines("%s %d %s %s" % row for row in rows)


def _low(catalog, movements, options):
    levels = shelves.stock_levels(catalog, movements)
    rows = []
    for sku in sorted(catalog):
        reorder = catalog[sku].reorder
        if shelves.status(levels[sku], reorder) != "ok":
            rows.append((sku, levels[sku], reorder, shelves.buy_quantity(levels[sku], reorder)))
    if options["json"]:
        return _dump(
            [{"sku": s, "onhand": o, "reorder": r, "buy": b} for s, o, r, b in rows]
        )
    return _lines("%s %d %d %d" % row for row in rows)


def _known_sku(text, catalog):
    if SKU_RE.fullmatch(text) and text.upper() in catalog:
        return text.upper()
    raise Refusal("unknown SKU %r" % text)


def _history(catalog, movements, positionals, options):
    sku = _known_sku(positionals[0], catalog)
    rows = shelves.history(sku, movements)
    if options["json"]:
        return _dump(
            [
                {
                    "date": m.date.isoformat(),
                    "delta": "%+d" % m.quantity,
                    "balance": balance,
                    "note": m.note,
                }
                for m, balance in rows
            ]
        )
    return _lines(
        "%s %+d %d%s" % (m.date.isoformat(), m.quantity, balance, " " + m.note if m.note else "")
        for m, balance in rows
    )


def _move(command, directory, catalog, movements, existing, positionals, date):
    sku = _known_sku(positionals[1], catalog)
    qty_text = positionals[2]
    if not re.fullmatch(r"[0-9]+", qty_text):
        raise Refusal("bad quantity %r (a whole number of one or more)" % qty_text)
    try:
        quantity = int(qty_text)
    except ValueError:
        raise Refusal("quantity %r is too large" % qty_text) from None
    if quantity < 1:
        raise Refusal("bad quantity %r (a whole number of one or more)" % qty_text)
    note = positionals[3] if len(positionals) == 4 else ""
    if "\n" in note or "\r" in note:
        raise Refusal("a note may not contain a line break")
    note = note.strip(" \t")
    delta = quantity if command == "receive" else -quantity
    candidate = Movement(date, sku, delta, note)
    bad = shelves.first_negative(list(movements) + [candidate])
    if bad is not None:
        who = (list(movements) + [candidate])[bad]
        raise Refusal(
            "stock of %s would go below zero on %s" % (who.sku, who.date.isoformat())
        )
    line = "%s %s %+d%s" % (date.isoformat(), sku, delta, " " + note if note else "")
    _append(directory, existing, line + "\n")
    return line + "\n"


def _quote_text(quote, header):
    rows = [header]
    for ln in quote.lines:
        rows.append(
            "%s %d %s %s %s %s"
            % (
                ln.sku,
                ln.quantity,
                _amount(ln.unit),
                _amount(ln.gross),
                _amount(ln.discount),
                _amount(ln.net),
            )
        )
    rows.append("subtotal " + _amount(quote.subtotal))
    rows.append("order discount " + _amount(quote.order_discount))
    rows.append("tax " + _amount(quote.tax))
    rows.append("total " + _amount(quote.total))
    return _lines(rows)


def _quote_json(order, quote):
    return _dump(
        {
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [
                {
                    "sku": ln.sku,
                    "quantity": ln.quantity,
                    "unit": _amount(ln.unit),
                    "gross": _amount(ln.gross),
                    "discount": _amount(ln.discount),
                    "net": _amount(ln.net),
                }
                for ln in quote.lines
            ],
            "subtotal": _amount(quote.subtotal),
            "order_discount": _amount(quote.order_discount),
            "tax": _amount(quote.tax),
            "total": _amount(quote.total),
        }
    )


def _find_order(orders, text):
    if ORDER_ID_RE.fullmatch(text):
        wanted = "SO-" + text[3:]
        for order in orders:
            if order.id == wanted:
                return order
    raise Refusal("unknown order %r" % text)


def _quote(catalog, orders, positionals, options, prefix=""):
    order = _find_order(orders, positionals[0])
    quote = price_order(order, catalog)
    if options["json"]:
        return _quote_json(order, quote)
    header = "%s%s %s %s" % (prefix, order.id, order.date.isoformat(), order.customer)
    return _quote_text(quote, header)


def _invoice(catalog, movements, orders, positionals, options):
    order = _find_order(orders, positionals[0])
    shipped = orders_mod.invoice_order(order, movements)
    if shipped is None:
        raise Refusal("nothing has shipped for %s" % order.id)
    quote = price_order(shipped, catalog)
    if options["json"]:
        return _quote_json(shipped, quote)
    header = "invoice %s %s %s" % (shipped.id, shipped.date.isoformat(), shipped.customer)
    return _quote_text(quote, header)


def _fulfil(directory, movements, existing, orders, positionals, date):
    order = _find_order(orders, positionals[0])
    if date < order.date:
        raise Refusal(
            "%s cannot be fulfilled on %s, before its order date %s"
            % (order.id, date.isoformat(), order.date.isoformat())
        )
    results, state = orders_mod.plan_fulfil(order, date, movements)
    added = "".join(
        "%s %s -%d order %s\n" % (date.isoformat(), sku, now, order.id)
        for sku, now, _ in results
        if now > 0
    )
    if added:
        _append(directory, existing, added)
    rows = ["%s shipped %d backordered %d" % row for row in results]
    rows.append("status " + state)
    return _lines(rows)


def _report(catalog, movements, orders, options):
    rows = orders_mod.report_rows(orders, catalog, movements)
    fmt = options["format"]
    if fmt == "json":
        return _dump(
            [
                dict(row, quoted=_amount(row["quoted"]), invoiced=_amount(row["invoiced"]))
                for row in rows
            ]
        )
    if fmt == "csv":
        out = io.StringIO()
        writer = csv.writer(out, lineterminator="\n")
        writer.writerow(
            ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        )
        for r in rows:
            writer.writerow(
                [
                    r["order"], r["date"], r["customer"], r["status"],
                    r["ordered"], r["shipped"], _amount(r["quoted"]), _amount(r["invoiced"]),
                ]
            )
        return out.getvalue()
    return _lines(
        "%s %s %s %s %d/%d %s %s"
        % (
            r["order"], r["date"], r["customer"], r["status"], r["shipped"], r["ordered"],
            _amount(r["quoted"]), _amount(r["invoiced"]),
        )
        for r in rows
    )


def _run(argv) -> str:
    command, directory, positionals, options, date = _parse_args(argv)
    directory = "." if directory is None else directory
    if not os.path.isdir(directory):
        raise FileProblem("%s: not a folder" % directory)

    need_movements, need_orders = _FILES[command]
    raw_catalog = _read(directory, CATALOG, True)
    raw_movements = _read(directory, MOVEMENTS, False) if need_movements else b""
    raw_orders = _read(directory, ORDERS, False) if need_orders else b""

    catalog = _parse(CATALOG, parse_catalog, raw_catalog.decode("utf-8"))
    movements = []
    orders = []
    if need_movements:
        movements = _parse(MOVEMENTS, parse_movements, raw_movements.decode("utf-8"), catalog)
    if need_orders:
        orders = _parse(ORDERS, parse_orders, raw_orders.decode("utf-8"), catalog)

    if command == "stock":
        return _stock(catalog, movements, options)
    if command == "low":
        return _low(catalog, movements, options)
    if command == "history":
        return _history(catalog, movements, positionals, options)
    if command in ("receive", "ship"):
        return _move(command, directory, catalog, movements, raw_movements, positionals, date)
    if command == "quote":
        return _quote(catalog, orders, positionals, options)
    if command == "fulfil":
        return _fulfil(directory, movements, raw_movements, orders, positionals, date)
    if command == "invoice":
        return _invoice(catalog, movements, orders, positionals, options)
    return _report(catalog, movements, orders, options)


# --------------------------------------------------------------------- main

def _emit(text: str) -> None:
    out = sys.stdout
    buffer = getattr(out, "buffer", None)
    if buffer is not None:
        out.flush()
        buffer.write(text.encode("utf-8"))
        buffer.flush()
    else:
        out.write(text)
        out.flush()


def _quiet_stdout() -> None:
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def _complain(message: str) -> None:
    try:
        sys.stderr.write("stockroom: %s\n" % message)
        sys.stderr.flush()
    except (OSError, ValueError):
        pass


def main(argv=None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    try:
        output = _run(list(argv))
    except UsageError as err:
        _complain(str(err))
        try:
            sys.stderr.write(USAGE)
            sys.stderr.flush()
        except (OSError, ValueError):
            pass
        return 2
    except FileProblem as err:
        _complain(str(err))
        return 2
    except Refusal as err:
        _complain(str(err))
        return 1
    if output:
        try:
            _emit(output)
        except BrokenPipeError:
            _quiet_stdout()
    return 0


if __name__ == "__main__":
    sys.exit(main())
